-- First run 20261013034836_basket_photo_ocr_db.version-check.sql and require known PostgreSQL 16+.
-- Read-only API requests may run as a read-only role: read pg_constraint (information_schema hides
-- tables owned by other roles) and name the apply executor postgres instead of current_user.
-- SELECT only. Applied and unused rollback modes share this structural check.
-- Row/ACL/policy/old-RPC identity still requires the saved snapshot comparison.
with state as(select exists(select 1 from supabase_migrations.schema_migrations where version='20261013034836' and name='basket_photo_ocr_db') applied),fn as(select p.* from pg_proc p where p.oid=to_regprocedure('public.app_basket_update_attachment_ocr(uuid,timestamptz,jsonb,jsonb)'))
select 'mode-specific OCR capability' item,case when (select applied from state) then exists(select 1 from fn where not prosecdef and proconfig=array['search_path=""'] and md5(prosrc)='47c2940148186abd4f02149499c4b084') else not exists(select 1 from fn) end ok
union all select 'RPC client grants',case when (select applied from state) then has_function_privilege('authenticated','public.app_basket_update_attachment_ocr(uuid,timestamptz,jsonb,jsonb)','EXECUTE') and not has_function_privilege('anon','public.app_basket_update_attachment_ocr(uuid,timestamptz,jsonb,jsonb)','EXECUTE') and not has_function_privilege('service_role','public.app_basket_update_attachment_ocr(uuid,timestamptz,jsonb,jsonb)','EXECUTE') and not exists(select 1 from fn f cross join lateral aclexplode(coalesce(f.proacl,acldefault('f',f.proowner)))a where a.grantee not in(f.proowner,'authenticated'::regrole) and a.privilege_type='EXECUTE') else not exists(select 1 from fn) end
union all select 'mode-specific attachments CHECK',(select count(*) from pg_constraint where connamespace='public'::regnamespace and conname='app_notes_attachments_check')=1 and exists(select 1 from pg_constraint where conrelid='public.app_notes'::regclass and conname='app_notes_attachments_check' and contype='c' and convalidated) and case when (select applied from state) then exists(select 1 from pg_constraint where conrelid='public.app_notes'::regclass and conname='app_notes_attachments_check' and convalidated and md5(btrim(regexp_replace(pg_get_constraintdef(oid),'\s+',' ','g')))='f64d48a74302742e31fa18b81355c9c1') else exists(select 1 from pg_constraint where conrelid='public.app_notes'::regclass and conname='app_notes_attachments_check' and contype='c' and convalidated
 and btrim(regexp_replace(pg_get_constraintdef(oid),'\s+',' ','g'))=btrim(regexp_replace('CHECK ('||'
CASE
    WHEN (jsonb_typeof(attachments) = ''array''::text) THEN ((jsonb_array_length(attachments) <= 20) AND (NOT jsonb_path_exists(attachments, ''strict $[*]?(@.type() != "object")''::jsonpath)) AND (NOT jsonb_path_exists(attachments, ''$[*]?((((((((((((((@.type() != "object" || !(exists (@."drive_file_id"))) || !(exists (@."file_name"))) || !(exists (@."mime_type"))) || !(exists (@."size_bytes"))) || @."drive_file_id".type() != "string") || !(@."drive_file_id" like_regex "^[A-Za-z0-9_-]{1,255}$")) || @."file_name".type() != "string") || !(@."file_name" like_regex "^.{1,255}$" flag "s")) || @."mime_type".type() != "string") || !(@."mime_type" like_regex "^[^/[:space:]]{1,127}/[^/[:space:]]{1,127}$")) || @."size_bytes".type() != "number") || @."size_bytes" < 1) || @."size_bytes" > 104857600) || @."size_bytes" != @."size_bytes".floor())''::jsonpath)) AND (NOT jsonb_path_exists(attachments, ''$[*].keyvalue()?(((@."key" != "drive_file_id" && @."key" != "file_name") && @."key" != "mime_type") && @."key" != "size_bytes")''::jsonpath)))
    ELSE false
END'||')','\s+',' ','g'))) end
union all select 'auth execution paths supported',not exists(select 1 from pg_auth_members where roleid='authenticated'::regrole and member<>'postgres'::regrole and (inherit_option or member not in(select oid from pg_roles where rolname in('authenticator','supabase_realtime_admin') and not rolinherit)))
union all select 'notes triggers absent',not exists(select 1 from pg_trigger where tgrelid='public.app_notes'::regclass and not tgisinternal)
union all select 'existing confirmation and summary exist',to_regprocedure('public.app_basket_confirm_links(uuid,timestamptz,jsonb)')is not null and to_regprocedure('public.app_basket_update_link_summary(uuid,text,text)')is not null
union all select 'notes owner RLS',exists(select 1 from pg_class c join pg_policy p on p.polrelid=c.oid where c.oid='public.app_notes'::regclass and c.relrowsecurity and p.polname='notes_owner_all');
